{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 금연환경 조성 및 간접흡연 피해방지조례상 시장이 금연구역 지정을 해제할 때 서울특별시보에 고시해야 하는지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "조례 제6조제2항은 금연구역의 지정 변경 또는 해제에 관한 사항에 제5조제2항과 제5조제3항을 준용하도록 정하고 있다. 제5조제3항은 시장이 금연구역을 지정하는 경우에 서울특별시보에 고시하도록 규정하고 있으므로, 지정 시 고시 의무를 정한 규정이다. 해제에 대해서는 별도로 고시 의무를 정한 규정이 없어, 해제 시 서울특별시보 고시 의무가 있다고 단정할 수 없다.",
          "b_ids": "금연:제6조제2항, 금연:제5조제3항"
        }
      ],
      "e_status": "CORE_MISSING"
    }
  ]
}
